payload.template:
// Classify a byte into a band, and report its parity.
//
// This implementation is BROKEN, and the simulator does not complain
// about it. Find the bug and fix it; the specification is in the
// problem statement, and any implementation that meets it is accepted.

module byte_class (
    input  logic       vld,
    input  logic [7:0] data,
    output logic [1:0] kind,   // 0 nothing, 1 low, 2 mid, 3 high
    output logic       odd     // parity of data, and 0 when not valid
);

    always_comb begin
        odd = vld & (^data);
        if (vld) begin
            if (data < 8'd64)       kind = 2'd1;
            else if (data < 8'd192) kind = 2'd2;
            else                    kind = 2'd3;
        end
    end

endmodule

payload.testbench:
`timescale 1ns/1ps

// The sample testbench. Submit uses another one, which goes round the
// bands in several orders.
module tb;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic       vld  = 1'b0;
  logic [7:0] data = 8'd0;
  logic [1:0] kind;
  logic       odd;

  byte_class dut (.vld(vld), .data(data), .kind(kind), .odd(odd));

  // The design is combinational; the clock is here only so the
  // waveform has something to line up against.
  task present(input logic v, input [7:0] d);
    begin
      @(negedge clk); vld = v; data = d;
      #1;
    end
  endtask

  logic [1:0] k_low, k_mid, k_high, k_invalid;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    present(1'b1, 8'd10);  k_low     = kind;
    present(1'b1, 8'd100); k_mid     = kind;
    present(1'b1, 8'd250); k_high    = kind;
    present(1'b0, 8'd250); k_invalid = kind;

    $display("CHECK low_band 1 %0d AT %0d", k_low, $time);
    $display("CHECK mid_band 2 %0d AT %0d", k_mid, $time);
    $display("CHECK high_band 3 %0d AT %0d", k_high, $time);
    $display("CHECK zero_when_not_valid 0 %0d AT %0d", k_invalid, $time);
    $display("DONE 4");
    $finish;
  end

endmodule
